    "musicModels1im3u": "Music models.",
    "openThePageTitle1edk4": "Open the page title to switch pages. Speak turns text into speech, Clone speaks in the voice from a short recording, Edit changes words in a recording, Convert makes a recording sound like another voice, Music makes songs and sound effects, Separate splits a track into vocals and instruments, and Transcribe turns a recording into text. Each lists only the models that can do it, so the picker above follows the page.",
    "promptResolutionDurationIn1rxvi": "Prompt, resolution, duration in frames, steps, guidance and seed. Duration and resolution drive VRAM and time most, so start small.",
    "qLoRATrainsAdaptersOn49tuo": "QLoRA trains adapters on a 4-bit base and needs the least VRAM. LoRA does the same in 16-bit. Full fine-tune updates every weight. Continued pretraining is for teaching a new domain or language.",
    "recipesAreStoredOn1p6oi": "Recipes are stored on this device. Save before a long run.",
    "recordFromYourMicrophonecujmp": "Record from your microphone and it transcribes when you stop, or upload a wav, mp3, m4a or webm file instead.",
